import { test, expect } from '@playwright/test';

test.describe('File Upload Retry Functionality', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/file-upload');
  });

  test('should retry a failed upload without re-selecting the file', async ({ page }) => {
    // Setup: Intercept the upload API endpoint
    await page.route('**/api/upload', (route) => {
      route.abort('failed');
    });

    // Setup: Intercept the retry API endpoint
    await page.route('**/api/upload/retry', (route) => {
      route.continue();
    });

    // Locate and interact with file input using getByLabel
    const fileInput = page.getByLabel('Select file');
    await fileInput.setInputFiles('playwright/fixtures/test-file.pdf');

    // Locate and click upload button using getByRole
    const uploadButton = page.getByRole('button', { name: 'Upload' });
    await uploadButton.click();

    // Verify upload failed
    const errorMessage = page.getByText('Upload failed');
    await expect(errorMessage).toBeVisible();

    // Verify retry button is visible
    const retryButton = page.getByRole('button', { name: 'Retry' });
    await expect(retryButton).toBeVisible();

    // Click retry button using getByRole
    await retryButton.click();

    // Verify retry request was sent
    await page.waitForResponse(response =>
      response.url().includes('/api/upload/retry') && response.status() === 200
    );

    // Verify success message appears
    const successMessage = page.getByText('Upload successful');
    await expect(successMessage).toBeVisible();

    // Verify file name is still displayed
    const fileNameDisplay = page.getByText('test-file.pdf');
    await expect(fileNameDisplay).toBeVisible();
  });

  test('should handle multiple retry attempts and display final status', async ({ page }) => {
    // Setup: Intercept the upload API endpoint
    await page.route('**/api/upload', (route) => {
      route.abort('failed');
    });

    // Setup: Intercept the retry API endpoint - first two fail, third succeeds
    let retryCount = 0;
    await page.route('**/api/upload/retry', (route) => {
      retryCount++;
      if (retryCount <= 2) {
        route.abort('failed');
      } else {
        route.continue();
      }
    });

    // Locate and interact with file input using getByLabel
    const fileInput = page.getByLabel('Select file');
    await fileInput.setInputFiles('playwright/fixtures/test-file.pdf');

    // Locate and click upload button using getByRole
    const uploadButton = page.getByRole('button', { name: 'Upload' });
    await uploadButton.click();

    // Verify initial failure
    const errorMessage = page.getByText('Upload failed');
    await expect(errorMessage).toBeVisible();

    // Click retry button using getByRole
    const retryButton = page.getByRole('button', { name: 'Retry' });
    await retryButton.click();

    // Verify first retry failed
    await page.waitForResponse(response =>
      response.url().includes('/api/upload/retry') && response.status() === 500
    );
    await expect(errorMessage).toBeVisible();

    // Click retry button again
    await retryButton.click();

    // Verify second retry failed
    await page.waitForResponse(response =>
      response.url().includes('/api/upload/retry') && response.status() === 500
    );
    await expect(errorMessage).toBeVisible();

    // Click retry button for third time (should succeed)
    await retryButton.click();

    // Verify success message appears
    const successMessage = page.getByText('Upload successful');
    await expect(successMessage).toBeVisible();

    // Verify retry button is no longer visible
    await expect(retryButton).not.toBeVisible();
  });
});
